/// <summary>
/// The <c>AVAWHSProcessGuidePromptCoilCalculatorResultStep</c> class represents the step to show the calculation data
/// </summary>
[
    ProcessGuideStepName(classStr(AVAWHSProcessGuidePromptCoilCalculatorResultStep))
]
class AVAWHSProcessGuidePromptCoilCalculatorResultStep extends ProcessGuideStep
{
}

Method.Source:
protected final boolean isComplete()
{
    boolean             ret;
    WhsrfPassthrough    avaLocalPass = controller.parmSessionState().parmPass();

    if (WHSRFMenuItemTable::find(avaLocalPass.parmMenuItem()).AVAAllowPostAdjustment == NoYes::Yes)
    {
        if (avaLocalPass.avaParmCoilWeight() != 0)
        {
            ret = true;
        }
    }
    else
    {
        ret = true;
    }

    return ret;
}
